// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the recipients array length and a single value; the fuzzer will supply addresses and amounts.
    // We use a small array size bound but allow any addresses/amounts; keep domain wide so mutant can be found.
    function testFuzz_property(address[] memory tos, uint256[] memory v) public {
        // keep arrays non-empty and same length as required by contract
        vm.assume(tos.length > 0 && tos.length == v.length);
        // ensure length reasonable to avoid OOG in fuzzing environment
        vm.assume(tos.length <= 10);

        // The contract's transfer requires msg.sender to be a specific hardcoded address.
        // The fuzzer cannot set msg.sender directly, so we impersonate that address.
        address owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.startPrank(owner);
        bool ok;
        try c.transfer(tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The universal property: for every admissible input (non-empty equal-length arrays, caller is owner),
        // the reference contract's transfer MUST return true when the call completes. The mutant that returns false
        // will make this assertion fail for some inputs; thus a single assertTrue observing c's public behavior:
        assertTrue(ok);
    }
}

