pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the tos array and values array; the adversarial callee is a benign contract that accepts the low-level call
    function testFuzz_property(address[] memory tos, uint256[] memory vals) public {
        // admissible domain: sender must be the required one and tos must be non-empty and lengths match
        address requiredSender = address(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        vm.assume(tos.length > 0);
        vm.assume(tos.length == vals.length);

        // deploy a helper that has code and whose fallback will succeed (so low-level call returns true)
        CalleeAccepting helper = new CalleeAccepting();

        // set c.caddress through storage: we cannot write internal storage directly, but C has a public caddress variable
        // however the contract under test initialized caddress statically; we instead will call transfer but route the
        // 'tos' parameter values to the helper by overwriting one of the tos entries to be helper so that the low-level
        // call targets a contract with code. The important part is that the callee exists (has code) so call returns true.

        // Ensure the fuzzed tos includes at least one remote address that is a contract (replace first entry)
        tos[0] = address(helper);

        // The reference contract requires msg.sender to equal the hardcoded address; emulate that
        vm.prank(requiredSender);

        // Call transfer and capture whether it completes and returns a bool
        bool ok;
        try c.transfer(tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false; // revert treated as false
        }

        // The universal property: on the reference C, for any admissible input (pranked sender and non-empty tos),
        // transfer completes and returns true. The mutant that returns false will violate this for some input.
        assertTrue(ok);
    }
}

// Minimal helper that accepts low-level calls and returns success
contract CalleeAccepting {
    fallback() external payable {
        // do nothing, succeed
    }
}
